function parse_collected(?string $v):?string{if(!$v)return null;$v=trim($v);if($v==='')return null;foreach(['!n/j/Y g:i:s A','!m/d/Y g:i:s A','!Y-m-d H:i:s'] as $f){$d=DateTime::createFromFormat($f,$v);if($d instanceof DateTime)return $d->format('Y-m-d H:i:s');}$ts=strtotime($v);return $ts!==false?date('Y-m-d H:i:s',$ts):null;}
function display_value(mixed $v):string{return is_array($v)?implode('، ',array_map('strval',$v)):(string)$v;}
function copy_prefix(array $source,array $keys):array{$out=[];foreach($keys as $k)if(array_key_exists($k,$source)&&$source[$k]!==''&&$source[$k]!==[])$out[$k]=$source[$k];return $out;}
