 if($step!=='review'&&$action==='analyze'){try{if(empty($_FILES['csv']['tmp_name'])||$_FILES['csv']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('فایل CSV انتخاب نشده است.');if(strtolower(pathinfo($_FILES['csv']['name'],PATHINFO_EXTENSION))!=='csv')throw new RuntimeException('فقط فایل CSV مجاز است.');$rows=$importer->rows($_FILES['csv']['tmp_name']);$record=$rows->current();if(!$record)throw new RuntimeException('فایل داده‌ای ندارد.');$record['_source_file']=basename($_FILES['csv']['name']);if($step==='computer'){$wizard['records']['computer']=$record;$wizard['records']['display']=array_merge($wizard['records']['display']??[],copy_prefix($record,['MonitorDetails','DisplayTechnology','DisplaySize','DisplayResolution','DisplaySerial','Connection']));$wizard['records']['printer']=array_merge($wizard['records']['printer']??[],copy_prefix($record,['PrinterType','PrinterCapabilities','ColorMode','Connection','NetworkSharing','Duplex','PrinterManufacturer','PrinterModel','PrinterSerial','IPAddresses']));$wizard['records']['scanner']=array_merge($wizard['records']['scanner']??[],copy_prefix($record,['ScannerType','ScannerResolution','ScannerConnection','ScannerDuplex','ScannerManufacturer','ScannerModel','ScannerSerial','IPAddresses']));}else{$wizard['records'][$step]=$record;}if(in_array($step,['printer','scanner'],true))unset($wizard['records'][$step]['MACAddresses']);$_SESSION['_hardware_wizard']=$wizard;redirect('asset_wizard.php?step='.$step);}catch(Throwable $e){$error=$e->getMessage();}}
 if($step!=='review'&&$action==='next'){$record=$wizard['records'][$step]??[];foreach((array)($_POST['technical']??[]) as $key=>$value){$text=trim((string)$value);if(in_array($key,$arrayFields,true)){$decoded=json_decode($text,true);$record[$key]=(json_last_error()===JSON_ERROR_NONE&&is_array($decoded))?array_values($decoded):($text===''?[]:$importer->split($text));}else$record[$key]=$text;}$record['asset_no']=trim((string)($_POST['asset_no']??''));$record['location']=trim((string)($_POST['location']??''));$record['personnel_id']=trim((string)($_POST['personnel_id']??''));if(!preg_match('/^\d{7}$/',$record['asset_no']))$error='شماره اموال باید دقیقاً ۷ رقم باشد.';elseif($record['location']==='')$error='مکان الزامی است.';else{$q=db()->prepare('SELECT asset_no FROM assets WHERE asset_no=?');$q->execute([$record['asset_no']]);if($q->fetchColumn())$error='شماره اموال '.$record['asset_no'].' قبلاً ثبت شده است. <a class="btn small" href="asset_edit.php?asset_no='.rawurlencode($record['asset_no']).'">ویرایش همان تجهیز</a>';else{$wizard['records'][$step]=$record;$_SESSION['_hardware_wizard']=$wizard;$i=array_search($step,$steps,true);redirect($i<count($steps)-1?'asset_wizard.php?step='.$steps[$i+1]:'asset_wizard.php?step=review');}}}
 if($step==='review'&&$action==='finish'){try{$seen=[];foreach($steps as $type){$r=$wizard['records'][$type]??[];$n=(string)($r['asset_no']??'');if(!preg_match('/^\d{7}$/',$n))throw new RuntimeException('شماره اموال مرحله '.$types[$type].' کامل یا معتبر نیست.');if(isset($seen[$n]))throw new RuntimeException('شماره اموال '.$n.' در دو مرحله تکرار شده است.');$seen[$n]=true;$q=db()->prepare('SELECT asset_no FROM assets WHERE asset_no=?');$q->execute([$n]);if($q->fetchColumn())throw new RuntimeException('شماره اموال '.$n.' قبلاً ثبت شده است؛ <a class="btn small" href="asset_edit.php?asset_no='.rawurlencode($n).'">ویرایش همان تجهیز</a>');}$db=db();$db->beginTransaction();$registeredAt=date('Y-m-d H:i:s');$registeredIp=$_SERVER['REMOTE_ADDR']??null;$registeredUser=(int)user()['id'];foreach($steps as $type){$r=$wizard['records'][$type];$technical=[];foreach($r as $k=>$v){if($k===''||$k[0]==='_'||isset($usageMap[$k])||in_array($k,['asset_no','location','personnel_id'],true))continue;if($type==='computer'&&in_array($k,['IPAddresses','MACAddresses','SubnetMasks','Gateways','DNSServers','MonitorDetails','PrinterType','PrinterCapabilities','ColorMode','NetworkSharing','Duplex'],true))continue;$technical[$k]=$v;}if($type==='display'&&isset($r['MonitorDetails']))$technical['MonitorDetails']=$r['MonitorDetails'];$hostname=$r['ComputerName']??$r['PrinterName']??$r['ScannerName']??$r['DisplayName']??null;$manufacturer=$r['Manufacturer']??$r['PrinterManufacturer']??$r['ScannerManufacturer']??$r['DisplayManufacturer']??'';$model=$r['Model']??$r['PrinterModel']??$r['ScannerModel']??$r['DisplayModel']??'';$serial=$r['SystemSerial']??$r['PrinterSerial']??$r['ScannerSerial']??$r['DisplaySerial']??'';$q=$db->prepare('INSERT INTO assets(asset_no,asset_type,device_subtype,hostname,personnel_id,location,manufacturer,model,serial_no,technical,status,source_file,created_by,updated_by,registration_ip,registration_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$r['asset_no'],$type,$r['device_subtype']??null,$hostname,($r['personnel_id']??'')!==''?(int)$r['personnel_id']:null,$r['location'],$manufacturer,$model,$serial,json_encode($technical,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),'active',$r['_source_file']??null,$registeredUser,$registeredUser,$registeredIp,$registeredAt]);if($type==='computer'){$vals=[];foreach($usageMap as $src=>$col)$vals[$col]=(($r[$src]??'')==='')?null:$r[$src];$q=$db->prepare('INSERT INTO usage_stats(asset_no,boot_count,normal_shutdown_count,unexpected_shutdown_count,user_shutdown_count,last_boot_time,last_shutdown_time,completed_session_count,current_session_hours,current_session_duration,total_usage_hours,total_usage_duration,average_session_hours,average_session_duration,longest_session_hours,longest_session_duration,collected_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE boot_count=VALUES(boot_count),normal_shutdown_count=VALUES(normal_shutdown_count),unexpected_shutdown_count=VALUES(unexpected_shutdown_count),user_shutdown_count=VALUES(user_shutdown_count),last_boot_time=VALUES(last_boot_time),last_shutdown_time=VALUES(last_shutdown_time),completed_session_count=VALUES(completed_session_count),current_session_hours=VALUES(current_session_hours),current_session_duration=VALUES(current_session_duration),total_usage_hours=VALUES(total_usage_hours),total_usage_duration=VALUES(total_usage_duration),average_session_hours=VALUES(average_session_hours),average_session_duration=VALUES(average_session_duration),longest_session_hours=VALUES(longest_session_hours),longest_session_duration=VALUES(longest_session_duration),collected_at=VALUES(collected_at)');$q->execute([$r['asset_no'],$vals['boot_count'],$vals['normal_shutdown_count'],$vals['unexpected_shutdown_count'],$vals['user_shutdown_count'],parse_collected($vals['last_boot_time']),parse_collected($vals['last_shutdown_time']),$vals['completed_session_count'],$vals['current_session_hours'],$vals['current_session_duration'],$vals['total_usage_hours'],$vals['total_usage_duration'],$vals['average_session_hours'],$vals['average_session_duration'],$vals['longest_session_hours'],$vals['longest_session_duration'],parse_collected($vals['collected_at'])]);}if($type==='computer')foreach($importer->disks($r) as $d){$q=$db->prepare('INSERT INTO asset_disks(asset_no,disk_index,model,size_gb,serial_no,interface_name,media) VALUES(?,?,?,?,?,?,?)');$q->execute([$r['asset_no'],$d['index'],$d['model'],$d['size_gb'],$d['serial_no'],$d['interface']??null,$d['media']??null]);}if($type==='computer')foreach($importer->ramSlots($r) as $ram){$q=$db->prepare('INSERT INTO asset_ram_slots(asset_no,slot_no,state,capacity_gb,ram_type,speed_mhz,manufacturer,part_number,serial_no) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$r['asset_no'],$ram['slot_no'],$ram['state']??'unknown',$ram['capacity_gb']??null,$ram['ram_type']??null,$ram['speed_mhz']??null,$ram['manufacturer']??null,$ram['part_number']??null,$ram['serial_no']??null]);}audit('hardware_wizard_asset_registered','asset',$r['asset_no'],['type'=>$type,'source'=>$r['_source_file']??null,'collected_at'=>$r['CollectedAt']??null,'registered_at'=>$registeredAt,'registered_ip'=>$registeredIp,'registered_by'=>$registeredUser]);}$db->commit();unset($_SESSION['_hardware_wizard']);flash('success','چهار تجهیز پس از تأیید نهایی با موفقیت ثبت شدند.');redirect('index.php');}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();$error=$e->getMessage();}}}
$wizard=$_SESSION['_hardware_wizard']??$wizard;$record=$wizard['records'][$step]??[];$people=db()->query('SELECT id,full_name,personnel_code FROM personnel ORDER BY full_name LIMIT 5000')->fetchAll();
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ثبت مرحله‌ای تجهیزات</title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">HWiNFO · سامانه پایش سخت‌افزار</a><nav><a href="index.php">داشبورد</a><a href="assets.php">تجهیزات</a><a href="report.php">گزارش‌ها</a><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><div class="eyebrow">Comprehensive Hardware Analysis, Monitoring and Reporting</div><h1><?=$step==='review'?'تأیید نهایی ثبت تجهیزات':'تحلیل '.$types[$step]?></h1><p class="muted">کامپیوتر ← چاپگر ← اسکنر ← نمایشگر ← تأیید نهایی. در تحلیل کامپیوتر، اطلاعات مانیتور/چاپگر/اسکنر در مرحله اختصاصی خود قرار می‌گیرد.</p></div></div><div class="wizard-steps"><?php foreach($steps as $i=>$s):$done=isset($wizard['records'][$s]['asset_no']);?><a class="wizard-step <?=$step===$s?'active ':''?><?=$done?'done':''?>" href="asset_wizard.php?step=<?=$s?>"><b><?=$i+1?></b><span><?=e($types[$s])?></span></a><?php endforeach;?><div class="wizard-step <?=$step==='review'?'active':''?>"><b>✓</b><span>تأیید نهایی</span></div></div><?php if($error):?><div class="alert danger"><?=$error?></div><?php endif;?><?php if($step!=='review'):?><section class="panel"><h2>خوانش CSV — <?=$types[$step]?></h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="step" value="<?=e($step)?>"><input type="hidden" name="action" value="analyze"><div class="upload-row"><input type="file" name="csv" accept=".csv,text/csv" required><button class="btn primary">تحلیل و تکمیل اطلاعات</button></div></form></section><form method="post" class="panel"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="step" value="<?=e($step)?>"><input type="hidden" name="action" value="next"><h2>تکمیل و تأیید <?=$types[$step]?></h2><div class="form-grid"><label>شماره اموال (۷ رقم)<input name="asset_no" inputmode="numeric" pattern="[0-9]{7}" maxlength="7" value="<?=e($record['asset_no']??'')?>" required oninput="checkAsset(this)"><div id="dup" class="duplicate-check"></div></label><label>مکان<input name="location" value="<?=e($record['location']??'')?>" required></label><?php if($step==='computer'):?><label>پرسنل / کاربر<select name="personnel_id"><option value="">انتخاب پرسنل</option><?php foreach($people as $p):?><option value="<?=$p['id']?>" <?=(string)($record['personnel_id']??'')===(string)$p['id']?'selected':''?>><?=e($p['full_name'].' — '.($p['personnel_code']??''))?></option><?php endforeach;?></select></label><?php endif;?></div><?php foreach($groups[$step] as $title=>$keys):$visible=array_filter($keys,fn($k)=>array_key_exists($k,$record)||$k==='NetworkDetails'||$k==='IPAddresses');?><div class="wizard-group"><h3><?=e($title)?></h3><div class="form-grid"><?php foreach($visible as $k):?><label><?=e($labels[$k]??$k)?><textarea name="technical[<?=e($k)?>]" rows="3" <?=in_array($k,$arrayFields,true)?'dir="ltr"':''?>><?=e(display_value($record[$k]??''))?></textarea></label><?php endforeach;?></div></div><?php endforeach;?><?php if($step==='computer'):?><div class="wizard-group"><h3>آمار استفاده و تاریخ ثبت اطلاعات</h3><div class="form-grid"><?php foreach($usageLabels as $k=>$lbl):?><label><?=e($lbl)?><input name="technical[<?=e($k)?>]" value="<?=e((string)($record[$k]??''))?>"></label><?php endforeach;?></div></div><?php endif;?><div class="actions"><button class="btn primary">ذخیره مرحله و ادامه</button><button type="submit" name="action" value="reset" class="btn">شروع مجدد</button></div></form><?php else:?><section class="panel"><h2>مرور نهایی</h2><p class="muted">هیچ تجهیزی قبل از این مرحله ثبت نهایی نمی‌شود. پس از تأیید، هر چهار تجهیز در یک تراکنش ثبت می‌شوند.</p><div class="review-grid"><?php foreach($steps as $s):$r=$wizard['records'][$s]??[];?><article class="panel review-card"><h3><?=e($types[$s])?> — <?=e($r['asset_no']??'تکمیل نشده')?></h3><div class="review-fields"><div><span>مکان</span><strong><?=e($r['location']??'—')?></strong></div><div><span>منبع</span><strong><?=e($r['_source_file']??'—')?></strong></div><?php if($s==='computer'):?><div><span>CollectedAt</span><strong><?=e($r['CollectedAt']??'—')?></strong></div><div><span>جلسات کامل</span><strong><?=e($r['CompletedSessionCount']??'—')?></strong></div><?php endif;?></div></article><?php endforeach;?></div><div class="actions"><a class="btn" href="asset_wizard.php?step=computer">بازگشت به ویرایش</a><form method="post" style="display:inline"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="step" value="review"><input type="hidden" name="action" value="finish"><button class="btn primary">تأیید نهایی و ثبت هر چهار تجهیز</button></form></div></section><?php endif;?></main><script>function checkAsset(el){const box=document.getElementById('dup'),n=el.value.trim();if(n.length!==7){box.classList.remove('show');return;}fetch('asset_check.php?asset_no='+encodeURIComponent(n),{headers:{'X-Requested-With':'XMLHttpRequest'}}).then(r=>r.json()).then(d=>{if(d.exists){box.innerHTML='شماره اموال تکراری است <a class="btn small" href="asset_edit.php?asset_no='+encodeURIComponent(n)+'">ویرایش همان تجهیز</a>';box.classList.add('show');}else{box.classList.remove('show');}}).catch(()=>{});}</script></body></html>
